INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon''s Lair II: Time Warp', 'Dragon''s Lair II: Time Warp, the followup to Don Bluth''s arcade classic Dragon''s Lair, can now be enjoyed on your PC. This fully arcade authentic version includes all of the original scenes you''ve come to enjoy, and even the unreleased Director''s Cut ending not seen in the arcades. Other bonuses include a full watch feature to sit back and enjoy Don Bluth''s stunning animation.' FROM games WHERE igdb_id = 14660 ON CONFLICT (game_id, language_code) DO NOTHING;
