INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wings of Wor', 'Gynoug, known in North America as Wings of Wor, is a 1991 scrolling shooter video game developed by Masaya and published by NCS Corporation for the Sega Genesis. The game was released in North America and Europe in 1991 and in Japan on January 25, 1991, and re-released on the Wii Virtual Console exclusively in Japan on May 20, 2008.' FROM games WHERE igdb_id = 105255 ON CONFLICT (game_id, language_code) DO NOTHING;
