INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alpha Mission II', 'Alpha Mission II is a 2D vertical scrolling shooter with a great deal of depth for two players moving vertically up the screen boards shooting anything that moves. Equip up to three pieces of armor, which also serve as weapons, for a variety of attacks such as the laser and flamethrower. Use them to defeat the evil “Fulvar” and save mankind!' FROM games WHERE igdb_id = 13681 ON CONFLICT (game_id, language_code) DO NOTHING;
