INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Terminator 2: Judgement Day', 'You are T-800 in the action packed game play of Terminator 2. This game takes place in the not too distant future that we may live to see. Battle rages between man and machines - machines that are being controlled by Skynet. In an effort to quash the rebellion, Skynet sends a terminator back through time to 1994 with a directive to destroy the rebel leader John Conner while still a child. T-800 is then sent by the rebels to protect their future leader.' FROM games WHERE igdb_id = 45346 ON CONFLICT (game_id, language_code) DO NOTHING;
