INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fatal Fury', 'Fatal Fury is a fighting game developed by SNK and released for arcades in 1991. Players choose from a roster of martial artists and compete in one-on-one battles using punches, kicks, and special moves. The game introduced a two-plane fighting system that allows characters to move between foreground and background lanes. Its story follows Terry Bogard and his allies as they challenge the crime lord Geese Howard.' FROM games WHERE igdb_id = 71128 ON CONFLICT (game_id, language_code) DO NOTHING;
