INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Duke Nukem: Episode 2 - Mission: Moonbase', 'Duke Nukem is the debut of the world’s greatest wise-cracking, alien-punching, gun-toting badass - a man who would later go on to combine both ass-kicking and bubblegum in a revolutionary way. In a world ravaged by Dr. Proton’s villainous ambitions, the original video game action hero must rise against the evil scientist’s army of sinister Techbots. And although Duke isn’t exactly what the Doctor ordered, he’s exactly what the world needed.' FROM games WHERE igdb_id = 129403 ON CONFLICT (game_id, language_code) DO NOTHING;
