INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TumblePop', 'Tumblepop is a 1991 platform arcade video game developed by Data East first published in Japan by Namco, then in North America by Leprechaun Inc. and later in Europe by Mitchell Corporation. Starring two ghosthunters, players are tasked with travelling across different countries, capturing enemies and throwing them as bouncing ball, jumping on and off platforms to navigate level obstacles while dodging and defeating monsters in order to save the world.' FROM games WHERE igdb_id = 25694 ON CONFLICT (game_id, language_code) DO NOTHING;
