INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teenage Mutant Ninja Turtles II: Back from the Sewers', 'Teenage Mutant Ninja Turtles II: Back from the Sewers, released as Teenage Mutant Hero Turtles II: Back from the Sewers in Europe, and simply Teenage Mutant Ninja Turtles 2 in Japan, is a 1991 Game Boy game by Konami. It is the sequel to Teenage Mutant Ninja Turtles: Fall of the Foot Clan.' FROM games WHERE igdb_id = 18639 ON CONFLICT (game_id, language_code) DO NOTHING;
