INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('burgertime-deluxe', 48958, '1991-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6aso.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1klb.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BurgerTime Deluxe', 'Based on BurgerTime, the Arcade classic from 1982, BurgerTime Deluxe once again puts you in the role of chef Peter Pepper, a guy who can really build a burger. You maneuver the cook up and down ladders and left and right across floors in order to walk across various parts of giant hamburgers, such as large lettuce, big buns and massive meat patties. After you cross any section of any hamburger, it will drop one level and push any other burger part within that stack down a floor as well. The object of the game is to build all the hamburgers in each stage by dropping all the makings of each burger into completed stacks at the bottom of the screen.
