INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man 4', 'For a year the city has been quiet, but a new robotic terror has gripped the city! That scheming scientist, Dr. Cossack has arrived in town with eight new metal maniacs who are bigger and badder than anything Dr. Wily dreamed of. It''s going to be a cybernetic showdown as the streets of the city erupt with the sizzling sounds of molten metal! Armed with the new Mega Buster, Mega Man runs, jumps and dodges his way through mazes of metallic munchkins on his way to the Siberian citadel of Dr. Cossack for the final cataclysmic clash!' FROM games WHERE igdb_id = 1717 ON CONFLICT (game_id, language_code) DO NOTHING;
