INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nostalgia 1907', 'Nostalgia 1907 is an adventure game developed and published by Sur de Wave. Originally released for the Sharp X68000, it was later ported to the FM Towns Marty, PC-9801, and Sega Mega CD. The player assumes the role of a passenger aboard a cruise liner named the Nostalgia that has been taken captive by a criminal looking for an artifact.' FROM games WHERE igdb_id = 5407 ON CONFLICT (game_id, language_code) DO NOTHING;
