INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bill Laimbeer''s Combat Basketball', 'The game predicts a science-fiction version of the year 2030 in which there are only robot basketball players (excluding Bill Laimbeer). Basketball teams play in gruelling league matches where new players are bought and sold. Within this future, basketball uses a dedicated robot to perform the toss up at the start of each match as referees had been fired by Bill Laimbeer sometime prior to the year 2030. As a result, players now wear armor to their games and weapons are thrown from the audience.' FROM games WHERE igdb_id = 46002 ON CONFLICT (game_id, language_code) DO NOTHING;
