INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kick Off 2: Return to Europe', 'Return to Europe is a data disk for Kick Off 2 that allows the player to participate in three major European Competitions: the UEFA Cup, the Cup Winners Cup and the European Cup. This was topical in the UK, as English clubs had just been readmitted into Europe, having been banned for several years following the Heysel stadium disaster of 1985.
