INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Kick-Off', 'Super Kick Off is a football game for the Sega Mega Drive, Sega Master System and Sega Game Gear, released exclusively in Europe and Brazil. It is considered by many to be the watered-down version of Kick Off 2, previously released for the Commodore Amiga (and ported to the Amstrad CPC, Atari ST and Commodore 64). Kick Off 2 was originally programmed by Dino Dini for Anco Games, with the console adaptions being handled by Tiertex.
