INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure Island II', 'Adventure Island II is a side-scrolling platform game developed by Now Production and published by Hudson Soft that was released for the Nintendo Entertainment System in 1991. It is the sequel to Adventure Island and the second game in the series for the NES. While the first game was an adaptation of Westone''s Wonder Boy arcade game, Adventure Island II is an entirely original work, as were all the subsequent Adventure Island games.' FROM games WHERE igdb_id = 6471 ON CONFLICT (game_id, language_code) DO NOTHING;
