INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('elemental-master', 46218, '1991-01-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5l6b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scuiiy.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elemental Master', 'Gyra has usurped the throne, and his minions are pillaging and plundering throughout the countryside. The kingdom is doomed unless someone can stop this madness and restore order to the land. You are the ELEMENTAL MASTER, and you''re the only person with the power to put an end to Gyra''s reign of terror. Harnessing the power of the elements fire, water, wind, and the earth you use them as your very own weapons to fight all that is evil in the world. You''ll be up against Gyra''s most ruthless henchmen as you battle through eight levels of intense action. But you''ve got the power of magic on your side, and if you can master the five spells at your disposal, you''ll be a nearly unstoppable force. Of course, when you''re single-handedly taking on an entire army, the odds are stacked against you. But with the power of the elements, you''re the only one who can stop Gyra and his army.' FROM games WHERE igdb_id = 46218 ON CONFLICT (game_id, language_code) DO NOTHING;
