INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astérix', 'The Romans have kidnapped Getafix, who is the only one that can brew the magic potion the Gauls need to stand against the Romans. Asterix and Obelix embark on a journey to free him. You can play as either Asterix or Obelix which play slightly differently (Obelix is slower, but can manipulate objects, Asterix moves faster).' FROM games WHERE igdb_id = 19486 ON CONFLICT (game_id, language_code) DO NOTHING;
