INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crisis Force', 'The denizens of Atlantis have arisen after a slumber of 10,000 years, and only Asuka and Maya can save the world from destruction in their Aurawing aircraft! Crisis Force was Konami''s last shoot-''em-up game for the Famicom, and it pushes the hardware to its absolute limits.' FROM games WHERE igdb_id = 48652 ON CONFLICT (game_id, language_code) DO NOTHING;
