INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic Pockets', 'Magic Pockets is a platform game developed by the Bitmap Brothers and published by Renegade in October 1991. It was released for the Atari ST, Amiga, Acorn Archimedes and PC. The title track of the game is the instrumental version of a hit single "Doin'' The Do", by Betty Boo, originally released in 1990 on the Rhythm King label.' FROM games WHERE igdb_id = 12181 ON CONFLICT (game_id, language_code) DO NOTHING;
