INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MiG-29 Fulcrum', 'The MiG-29 plane, nicknamed Fulcrum by the West, features in this flight simulation, professionally modeled by former British Aerospace flight simulator designers. You are armed with cannons, rockets, and Air-to-Air and Air-to-Ground missiles. Aerodynamics, blackouts, and physics are all recreated. There are six missions to take on, starting with your basic training.' FROM games WHERE igdb_id = 12682 ON CONFLICT (game_id, language_code) DO NOTHING;
