INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raiden Trad', 'Raiden Trad is an over-head vertical-scrolling shooter, based on an arcade game of the same title. It features two forms of weapon upgrades and two types of missiles (normal or homing). You start the game with several bombs which you can use to destroy most enemies on the screen to get yourself out of a jam. Each level ends with a large boss or bosses.' FROM games WHERE igdb_id = 46211 ON CONFLICT (game_id, language_code) DO NOTHING;
