INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road Rash', 'Road Rash is a high-octane motorcycle racing game where players become bikers competing in illegal races across the U.S.A. The game focuses on a series of races in California, which players must win to progress to more challenging competitions. Along the way, they engage in both unarmed and armed combat to outmaneuver other racers.' FROM games WHERE igdb_id = 3249 ON CONFLICT (game_id, language_code) DO NOTHING;
