INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darkman', 'The game''s plot is loosely based on the film of the same name. In this side-scrolling platformer, the player controls Darkman, a superhero who can jump, kick and punch, as well as swing from a rope during action sequences between levels. In each level, Darkman disguises himself as the boss of the level, whom he must defeat before the time limit elapses.' FROM games WHERE igdb_id = 12037 ON CONFLICT (game_id, language_code) DO NOTHING;
