INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blaster Master Boy', 'Blaster Master Jr., known as Blaster Master Boy in North America and Bomber King: Scenario 2 (ボンバーキング シナリオ2?) in Japan, is an action video game developed by Aicom and published by Sunsoft. The game was released in 1991 for Game Boy. The game is a sequel to Robowarrior, a spin-off title in the Bomberman series by Hudson Soft. However, the game was marketed in western territories as a game in the Blaster Master series by Sunsoft.' FROM games WHERE igdb_id = 7790 ON CONFLICT (game_id, language_code) DO NOTHING;
