INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tyrants: Fight Through Time', 'First you choose one out of four different characters to represent you, Scarlet (red army), Oberon (yellow army), Caesar (green army), or Madcap (blue army). The game is split into 10 levels - the first 9 are groups of 3 territories which can be completed in any order, while the final ''Mother of All Battles'' has its own surprises.
