INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Joe & Mac', 'The Super NES version of Joe & Mac is a reworked game which features an overworld map used to choose the levels (unlike in other versions where all of them have to be played), which were longer, plus some bonus stages (either in the levels or out in the world map) and a different final boss.' FROM games WHERE igdb_id = 213880 ON CONFLICT (game_id, language_code) DO NOTHING;
