INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Blues Brothers', 'The Blues Brothers video game was designed by Titus Software and is based on the comedic sketch band of the same name. The platformer-style game was released in 1991 for MS-DOS. It was subsequently ported to a number of other platforms, including the Amiga, Atari ST, and NES.' FROM games WHERE igdb_id = 7792 ON CONFLICT (game_id, language_code) DO NOTHING;
