INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eye of the Beholder', 'Eye of the Beholder is an all 3-D, Legend Series computer role-playing adventure based on the popular Advanced Dungeons & Dragons 2nd Edition rules and on an original story created for this game . The action takes place in the sewers and catacombs beneath the City of Waterdeep located in TSR''s Forgotten Realms game world.' FROM games WHERE igdb_id = 5384 ON CONFLICT (game_id, language_code) DO NOTHING;
